import socket


def close_quietly(sock: socket.socket) -> None:
    # 設計上の best-effort。終了処理は例外を投げてはならない。プロセスは既に
    # 終了中で peer が先に閉じている場合もあり、ここで上げた例外は本来の終了理由を
    # 覆い隠すだけである。握り潰しは意図であって欠陥ではない。
    try:
        sock.close()
    except:
        pass

